```java
package generated_program;

import com.pulumi.Context;
import com.pulumi.Pulumi;
import com.pulumi.core.Output;
import com.pulumi.launchdarkly.AiConfig;
import com.pulumi.launchdarkly.AiConfigArgs;
import com.pulumi.launchdarkly.AiAgentGraph;
import com.pulumi.launchdarkly.AiAgentGraphArgs;
import com.pulumi.launchdarkly.inputs.AiAgentGraphEdgesArgs;
import static com.pulumi.codegen.internal.Serialization.*;
import com.pulumi.resources.CustomResourceOptions;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Map;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;

public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        var triageAgent = new AiConfig("triageAgent", AiConfigArgs.builder()
            .projectKey(example.key())
            .key("triage-agent")
            .name("Triage agent")
            .mode("agent")
            .build());

        var supportAgent = new AiConfig("supportAgent", AiConfigArgs.builder()
            .projectKey(example.key())
            .key("support-agent")
            .name("Support agent")
            .mode("agent")
            .build(), CustomResourceOptions.builder()
                .dependsOn(triageAgent)
                .build());

        var supportWorkflow = new AiAgentGraph("supportWorkflow", AiAgentGraphArgs.builder()
            .projectKey(example.key())
            .key("support-workflow")
            .name("Support workflow")
            .description("Routes incoming requests from the triage agent to the support agent")
            .rootConfigKey(triageAgent.key())
            .edges(Map.of("triage-to-support", AiAgentGraphEdgesArgs.builder()
                .sourceConfig(triageAgent.key())
                .targetConfig(supportAgent.key())
                .handoff(serializeJson(
                    jsonObject(
                        jsonProperty("reason", "needs_human_support")
                    )))
                .build()))
            .build());

    }
}
