            },
            {
                attribute: "username",
                op: "startsWith",
                values: [
                    "henrietta",
                    "wally",
                ],
            },
            {
                attribute: "username",
                op: "matches",
                values: ["henr*"],
            },
            {
                attribute: "username",
                op: "contains",
                values: ["water"],
            },
            {
                attribute: "pageVisits",
                op: "lessThan",
                values: ["100"],
            },
            {
