            - attribute: country
              op: startsWith
              values:
                - en
                - de
                - un
              negate: false
              contextKind: location-data
  # This example shows a segment configured to have an unbounded number of individual targets
  big-example:
    type: launchdarkly:Segment
    properties:
      key: example-big-segment-key
      projectKey: ${exampleLaunchdarklyProject.key}
      envKey: ${exampleLaunchdarklyEnvironment.key}
      name: example big segment
      description: This big segment is managed by Terraform
      tags:
        - segment-tag-1
        - segment-tag-2
      unbounded: true
      unboundedContextKind: user
  # This example shows a segment with a targeting rule that uses all clause operators
  segmentWithAllClauseOperators:
    type: launchdarkly:Segment
    name: segment_with_all_clause_operators
    properties:
      name: Segment with all clause operators
      key: segment-operators
      projectKey: projectx
      envKey: development
      rules:
        - clauses:
            - attribute: username
              op: in
              values:
                - henrietta powell
                - wally waterbear
            - attribute: username
              op: endsWith
              values:
                - powell
                - waterbear
            - attribute: username
              op: startsWith
              values:
                - henrietta
                - wally
            - attribute: username
              op: matches
              values:
                - henr*
            - attribute: username
              op: contains
              values:
                - water
            - attribute: pageVisits
              op: lessThan
              values:
                - 100
            - attribute: pageVisits
              op: lessThanOrEqual
              values:
                - 100
            - attribute: pageVisits
              op: greaterThan
              values:
                - 100
            - attribute: pageVisits
              op: greaterThanOrEqual
              values:
                - 100
            - attribute: creationDate
              op: before
              values:
                - 2024-05-03T15:57:30Z
            - attribute: creationDate
              op: after
              values:
                - 2024-05-03T15:57:30Z
            - attribute: version
              op: semVerEqual
              values:
                - 1.0.0
                - 1.0.1
              contextKind: application
            - attribute: version
              op: semVerLessThan
              values:
                - 1.0.0
              contextKind: application
            - attribute: version
              op: semVerGreaterThan
              values:
                - 1.0.0
              contextKind: application
            - attribute: context
              op: segmentMatch
              values:
                - test-segment
  # Example: Segment with view associations
  # This approach is ideal for modular Terraform where each segment is managed in its own file
  #
  # Always reference the view rather than repeating its key as a string literal.
  # A view must exist before Terraform can link a segment to it, and Terraform only
  # knows to create the view first if the segment references it. With a string
  # literal there is no dependency between the two resources, so Terraform can
  # create the segment first and the apply fails with "view does not exist".
  # Referencing the view also rules out a mistyped key.
  salesTeam:
    type: launchdarkly:View
    name: sales_team
    properties:
      projectKey: example-project
      key: sales-team
      name: Sales Team
      maintainerTeamKey: sales
  customerSuccess:
    type: launchdarkly:View
    name: customer_success
    properties:
      projectKey: example-project
      key: customer-success
      name: Customer Success
      maintainerTeamKey: customer-success
  premiumUsers:
    type: launchdarkly:Segment
    name: premium_users
    properties:
      key: premium-users
      projectKey: example-project
      envKey: production
      name: Premium Users
      description: Users with premium subscriptions
      viewKeys:
        - ${salesTeam.key}
        - ${customerSuccess.key}
      tags:
        - premium
        - subscription
      rules:
        - clauses:
            - attribute: plan
              op: in
              values:
                - premium
                - enterprise
  betaTesters:
    type: launchdarkly:Segment
    name: beta_testers
    properties:
      key: beta-testers
      projectKey: example-project
      envKey: staging
      name: Beta Testers
      viewKeys:
        - ${productTeam.key}
      tags:
        - beta
        - testing
      includeds:
        - user123
        - user456
variables:
  # Example: Segment managed in a module that can specify its own views
  # This enables a modular structure where each team/domain can manage their segments
  # without needing to coordinate with a central view_links resource
  #
  # When the view is owned by another configuration or state (for example a
  # platform team's workspace), use the data source. This asserts the view already
  # exists, so a typo or a missing view fails during plan instead of mid-apply.
  productTeam:
    fn::invoke:
      function: launchdarkly:getView
      arguments:
        projectKey: example-project
        key: product-team
```
<!--End PulumiCodeChooser -->

